new file mode 100644
index 0000000..81099db
--- /dev/null
+++ b/packages/core/src/services/aep/case.ts
@@ -0,0 +1,132 @@
+import {skipNullsEverywhere} from '../../util';
+import {getAepClient, getAepConfig, getSalesforceEventConfig} from './client';
+import {validation} from './utils/constant';
+
+/**
+ * Build Case AEP header based on Salesforce Event Config
+ * Matches the XML structure for header configuration
+ */
+export const buildCaseAepHeader = (
+  salesforceConfig: ReturnType<typeof getSalesforceEventConfig>,
+  isB2C: boolean,
+) => ({
+  schemaRef: {
+    id: isB2C
+      ? salesforceConfig.schemaRef.crm.b2c.case.id
+      : salesforceConfig.schemaRef.crm.b2b.case.id,
+    contentType: salesforceConfig.schemaRef.contentType,
+  },
+  datasetId: isB2C
+    ? salesforceConfig.crm.b2c.case.datasetId
+    : salesforceConfig.crm.b2b.case.datasetId,
+  source: {
+    name: isB2C ? `CRM B2C - Case` : `CRM B2B - Case`,
+  },
+  imsOrgId: salesforceConfig.profile.imsOrgId,
+});
+
+/**
+ * Build Case xdmMeta based on Salesforce Event Config
+ */
+export const buildCaseXdmMeta = (
+  salesforceConfig: ReturnType<typeof getSalesforceEventConfig>,
+  isB2C: boolean,
+) => ({
+  schemaRef: {
+    id: isB2C
+      ? salesforceConfig.schemaRef.crm.b2c.case.id
+      : salesforceConfig.schemaRef.crm.b2b.case.id,
+    contentType: salesforceConfig.schemaRef.contentType,
+  },
+});
+
+/**
+ * Build timestamp in ISO format with timezone
+ */
+export const buildCaseTimestamp = () => {
+  return new Date().toISOString().replace(/\.\d{3}/, ``);
+};
+
+/**
+ * Salesforce Case implementation subflow
+ * Processes case data and prepares it for AEP based on parent record type
+ * Corresponds to salesforce-case-implementation-subflow in XML
+ *
+ * @param payload - Transformed payload containing case data
+ * @param isB2C - Whether this is a B2C case (true) or B2B case (false)
+ * @returns AEP-ready payload for streaming ingestion
+ */
+export const processSalesforceCaseForAEP = (
+  payload: any,
+  isB2C: boolean = true,
+): any => {
+  const salesforceConfig = getSalesforceEventConfig();
+
+  // Build case data array - mapObject equivalent from XML
+  const caseDataArray = [payload.case].map((caseItem: any) => {
+    const mappedCase: Record<string, any> = {};
+    Object.keys(caseItem || {}).forEach((key) => {
+      mappedCase[key] = caseItem[key];
+    });
+    return mappedCase;
+  });
+
+  // Build AEP payload based on record type - matching XML structure
+  const aepPayload = skipNullsEverywhere({
+    header: buildCaseAepHeader(salesforceConfig, isB2C),
+    body: {
+      xdmMeta: buildCaseXdmMeta(salesforceConfig, isB2C),
+      xdmEntity: {
+        _smarteurope: {
+          case: caseDataArray,
+          customerID: payload.customerID,
+          ...(isB2C
+            ? {gigyaUid: payload.gigyaUid}
+            : {
+                ...(payload.gigyaUid && {gigyaUid: payload.gigyaUid}),
+                ...(payload.gigyaBPID && {gigyaBPID: payload.gigyaBPID}),
+              }),
+        },
+        _id: `${payload.customerID || ``}${Date.now()}`,
+        timestamp: buildCaseTimestamp(),
+      },
+    },
+  });
+
+  return aepPayload;
+};
+
+/**
+ * Send Case data to AEP Streaming Ingestion
+ * Reusable function for both create and update operations
+ *
+ * @param payload - Transformed payload containing case data
+ * @param isB2C - Whether this is a B2C case (true) or B2B case (false)
+ * @returns AEP API response
+ */
+export const sendCaseToAEP = async (
+  payload: any,
+  isB2C: boolean = true,
+): Promise<any> => {
+  try {
+    // Process case data for AEP
+    const aepPayload = processSalesforceCaseForAEP(payload, isB2C);
+
+    // Get AEP configuration and client (still needed for client creation)
+    const aepConfig = getAepConfig();
+    const collectionId = aepConfig.adobedc.collection.idCrm;
+    const aepClient = await getAepClient();
+
+    // Send to AEP streaming ingestion
+    const response = await aepClient.post(
+      `/collection/${collectionId}/${validation}`,
+      skipNullsEverywhere(aepPayload),
+    );
+
+    return response.data;
+  } catch (error) {
+    throw new Error(
+      `Failed to send case to AEP: ${error instanceof Error ? error.message : String(error)}`,
+    );
+  }
+};

