export * from './logger';
export * from './axios';
export * from './region-const';
export * from './utilities';
export * from './event-publish';
export * from './signature-generator';
export * from './api-error';

/**
 * Process array of events with individual item processing function
 * @param events - Array of events or single event
 * @param processItem - Function to process individual event item
 * @param logger - Logger instance for logging
 * @returns Promise that resolves when all items are processed
 */
export async function processEventArray<T>(
  events: T | T[],
  processItem: (item: T, index?: number, array?: T[]) => Promise<void>,
  loggerInstance: any,
): Promise<void> {
  if (Array.isArray(events)) {
    loggerInstance.info(`Processing ${events.length} events in batch`);

    // Process each item in the array
    const results = await Promise.allSettled(
      events.map(async (eventItem, index) => {
        loggerInstance.debug(`Processing item ${index + 1}/${events.length}`);
        return await processItem(eventItem, index, events);
      }),
    );

    // Check for any failed processing
    const failedResults = results.filter(
      (result) => result.status === `rejected`,
    );
    if (failedResults.length > 0) {
      loggerInstance.error(`Some events failed to process`, {
        totalItems: events.length,
        failedCount: failedResults.length,
        successCount: results.length - failedResults.length,
      });
      throw new Error(
        `Failed to process ${failedResults.length} out of ${events.length} events`,
      );
    }

    loggerInstance.info(
      `🎉 All ${events.length} events processed successfully`,
    );
  } else {
    // Single item processing
    loggerInstance.info(`Processing single event`);
    await processItem(events);
    loggerInstance.info(`🎉 Single event processed successfully`);
  }
}

