changeList.full_content:
import {logger} from './logger';
import {mergeObjectArray, safeParseJson} from './utilities';

/**
 * Transform platform event data (shared logic for both case-feed and customer-feed)
 * Equivalent to platform-event-transformation sub-flow in XML
 */
export function transformPlatformEvent(payload: any): any {
  const result = JSON.parse(JSON.stringify(payload));

  // Log basic information (equivalent to XML logger)
  logger.info(`Salesforce event received`, {
    salesforceRecordId: payload?.Record_ID__c,
    eventReceived: new Date().toISOString(),
    parentRecordType: payload?.Parent_Record_Type__c,
    recordType: payload?.Record_Type__c,
    actionType: payload?.Action__c,
    objectType: payload?.Object_Name__c,
  });

  if (!result) {
    return result;
  }

  // Handle Data__c and DataX__c concatenation (equivalent to XML transformation logic)
  const mainArray = safeParseJson(result.Data__c, []);
  const extraArray = safeParseJson(result.DataX__c, []);

  const mergedArray = [...mainArray, ...extraArray];

  let combinedObject = mergeObjectArray(mergedArray);

  // Handle Consent field conversion (equivalent to XML step 3)
  if (combinedObject.Consent && typeof combinedObject.Consent === `string`) {
    combinedObject = {
      ...combinedObject,
      Consent: safeParseJson(combinedObject.Consent, combinedObject.Consent),
    };
  }

  result.Data__c = combinedObject;

  return result;
}

