+  lastViewedDate?: string;
+  createdDate?: string;
+  deleted?: boolean;
+  createdBy?: string;
+  closed?: boolean;
+  salesforceRecordID: string;
+  dateTimeClosed?: string;
+  parentCaseId?: string;
+  status?: string;
+  recordType?: string;
+}
+
+// Define complete payload structure - Using Partial to handle optional fields
+interface TransformedPayload {
+  platformEvent: Partial<PlatformEventData> & {
+    parentRecordType: string;
+    objectType: string;
+    salesforceRecordId: string;
+    actionType: string;
+  };
+  case: CaseData;
+  gigyaUid?: string;
+  gigyaBPID?: string;
+  customerID?: string;
+}
+
+// Constant definitions (matching XML constant configuration)
+const CONSTANTS = {
+  LEAD_RECORDS: [`Private_Customer`, `SME_Lead`, `Fleet_Lead`],
+  ACCOUNT_TYPE_PERSON_ACC: `PersonAccount`,
+  ACCOUNT_TYPE_BUSINESS_ACC: [`SME_Company`, `Fleet_Company`],
+  BUSINESS_CONTACT: `Business_Contact`,
+  ACTION_NEW: `Create`,
+  ACTION_UPDATE: `Update`,
+};
+
+/**
+ * Process single feed event - encapsulated core logic
+ */
+async function processSingleFeedEvent(
+  feedItem: SimplifiedPayload,
+): Promise<void> {
+  try {
+    // Step 1: Platform event transformation (corresponds to platform-event-transformation)
+    const transformedPayload = transformPlatformEvent(feedItem);
+    logger.debug(`✅ Platform event transformation completed`);
+
+    // Step 2: Record type routing (corresponds to record-type choice)
+    const preparedPayload = routeByRecordType(transformedPayload);
+    logger.debug(`✅ Record type routing completed`, {
+      parentRecordType: preparedPayload.platformEvent.parentRecordType,
+    });
+
+    // Step 3: Action type routing (corresponds to action-type choice)
+    await routeByActionType(preparedPayload);
+    logger.debug(`✅ Action type routing completed`);
+
+    logger.info(`🎉 Case Feed item processed successfully`, {
+      salesforceRecordId: preparedPayload.platformEvent.salesforceRecordId,
+      parentRecordType: preparedPayload.platformEvent.parentRecordType,
+      actionType: preparedPayload.platformEvent.actionType,
+      objectType: preparedPayload.platformEvent.objectType,
+    });
+  } catch (error) {
+    logger.error(`Error processing Case Feed item`, {
+      error: error instanceof Error ? error.message : String(error),
+      stack: error instanceof Error ? error.stack : undefined,
+    });
+    throw error;
+  }
+}
+
+/**
+ * Main handler function
+ */
+export const handler = async (event: CaseFeedEvent, _context: Context) => {
+  logger.info(`🚀 Processing Case Feed event`, {
+    eventId: event.id,
+    source: event.source,
+    detailType: Array.isArray(event.detail) ? `array` : typeof event.detail,
+    detailCount: Array.isArray(event.detail) ? event.detail.length : 1,
+    replayId: event[`replay-id`],
+  });
+
+  try {
+    // Use the reusable array processing function
+    await processEventArray(event.detail, processSingleFeedEvent, logger);
+  } catch (error) {
+    logger.error(`Error processing Case Feed event`, {
+      error: error instanceof Error ? error.message : String(error),
+      stack: error instanceof Error ? error.stack : undefined,
+      eventId: event.id,
+      source: event.source,
+    });
+    throw error;
+  }
+};
+
+/**
+ * Route by record type - corresponds to record-type choice selector
+ */
+function routeByRecordType(payload: any): TransformedPayload {
+  const parentRecordType = payload.Parent_Record_Type__c;
+  logger.debug(` Routing by record type`, {parentRecordType});
+
+  // Lead record type processing
+  if (CONSTANTS.LEAD_RECORDS.includes(parentRecordType)) {
+    logger.info(` Processing Lead record type case`);
+    return prepareRequestCaseLead(payload);
+  }
+
+  // PersonAccount record type processing
+  if (parentRecordType === CONSTANTS.ACCOUNT_TYPE_PERSON_ACC) {
+    logger.info(` Processing PersonAccount record type case`);
+    return prepareRequestCaseB2CAccount(payload);
+  }
+
+  // Business Account record type processing
+  if (CONSTANTS.ACCOUNT_TYPE_BUSINESS_ACC.includes(parentRecordType)) {
+    logger.info(` Processing Business Account record type case`);
+    return prepareRequestCaseB2BAccount(payload);
+  }
+
+  // Business Contact record type processing
+  if (parentRecordType === CONSTANTS.BUSINESS_CONTACT) {
+    logger.info(` Processing Business Contact record type case`);
+    return prepareCaseB2BContact(payload);
+  }
+
+  // Invalid record type
+  const errorMsg = `Invalid Record-type: ${parentRecordType}`;
+  logger.error(`❌ Invalid record type received`, {
+    parentRecordType,
+    validTypes: [
+      ...CONSTANTS.LEAD_RECORDS,
+      CONSTANTS.ACCOUNT_TYPE_PERSON_ACC,
+      ...CONSTANTS.ACCOUNT_TYPE_BUSINESS_ACC,
+      CONSTANTS.BUSINESS_CONTACT,
+    ],
+  });
+  throw new Error(errorMsg);
+}
+
+/**
+ * Prepare Lead type Case request - corresponds to prepare-request-case-lead
+ */
+function prepareRequestCaseLead(payload: any): TransformedPayload {
+  logger.debug(` Preparing request for Lead case`);
+
+  const data = payload.Data__c;
+
+  return {
+    platformEvent: {
+      registrationType: data?.Registration_Type__c,
+      objectType: payload.Object_Name__c,
+      salesforceRecordId: payload.Record_ID__c,
+      parentRecordType: payload.Parent_Record_Type__c,
+      actionType: payload.Action__c,
+    },
+    case: prepareCaseData(data),
+    gigyaUid: data?.Parent_External_ID__c,
+    customerID: data?.LeadId__c,
+  };
+}
+
+/**
+ * Prepare B2C Account type Case request - corresponds to prepare-request-case-b2c-account
+ */
+function prepareRequestCaseB2CAccount(payload: any): TransformedPayload {
+  logger.debug(`📋 Preparing request for B2C Account case`);
+
+  const data = payload.Data__c;
+
+  return {
+    platformEvent: {
+      registrationType: data?.Registration_Type__c,
+      objectType: payload.Object_Name__c,
+      salesforceRecordId: payload.Record_ID__c,
+      parentRecordType: payload.Parent_Record_Type__c,
+      actionType: payload.Action__c,
+    },
+    case: prepareCaseData(data),
+    gigyaUid: data?.Parent_External_ID__c,
+    customerID: data?.AccountId,
+  };
+}
+
+/**
+ * Prepare B2B Account type Case request - corresponds to prepare-request-case-b2b-account
+ */
+function prepareRequestCaseB2BAccount(payload: any): TransformedPayload {
+  logger.debug(`📋 Preparing request for B2B Account case`);
+
+  const data = payload.Data__c;
+
+  return {
+    platformEvent: {
+      registrationType: data?.Registration_Type__c,
+      objectType: payload.Object_Name__c,
+      salesforceRecordId: payload.Record_ID__c,
+      parentRecordType: payload.Parent_Record_Type__c,
+      actionType: payload.Action__c,
+    },
+    case: prepareCaseData(data),
+    gigyaBPID: data?.Parent_External_ID__c,
+    customerID: data?.AccountId,
+  };
+}
+
+/**
+ * Prepare B2B Contact type Case request - corresponds to prepare-case-b2b-contact
+ */
+function prepareCaseB2BContact(payload: any): TransformedPayload {
+  logger.debug(`📋 Preparing request for B2B Contact case`);
+
+  const data = payload.Data__c;
+
+  return {
+    platformEvent: {
+      registrationType: data?.Registration_Type__c,
+      objectType: payload.Object_Name__c,
+      salesforceRecordId: payload.Record_ID__c,
+      parentRecordType: payload.Parent_Record_Type__c,
+      actionType: payload.Action__c,
+    },
+    case: prepareCaseData(data),
+    gigyaUid: data?.Parent_External_ID__c,
+    customerID: data?.ContactId,
+  };
+}
+
+/**
+ * Generic Case data preparation function
+ * Handles all Case field date format conversion and boolean conversion
+ */
+function prepareCaseData(data: any): CaseData {
+  logger.debug(`⚙️ Preparing case data with field transformations`);
+
+  // Handle case where data might be null or undefined
+  if (!data) {
+    logger.warn(
+      `⚠️ Case data is null or undefined, returning minimal case data`,
+    );
+    return {
+      salesforceRecordID: ``,
+    } as CaseData;
+  }
+
+  const caseData: CaseData = {
+    internalComments: data?.Comments,
+    caseOriginSubcategory: data?.OriginSubcategory__c,
+    subject: data?.Subject,
+    description: data?.Description,
+    ownerId: data?.OwnerId,
+    caseType: data?.Type,
+    caseNumber: data?.CaseNumber,
+    caseOrigin: data?.Origin,
+    contactMobile: data?.ContactMobile,
+    contactEmail: data?.ContactEmail,
+    lastModifiedBy: data?.LastModifiedById,
+    priority: data?.Priority,
+    caseReason: data?.Reason,
+    createdBy: data?.CreatedById,
+    salesforceRecordID: data?.Id || ``,
+    parentCaseId: data?.ParentId,
+    status: data?.Status,
+    recordType: data?.Record_Type__c,
+  };
+
+  // Handle optional fields and log conversions
+  const transformations: string[] = [];
+
+  if (data?.LastModifiedDate) {
+    caseData.lastModifiedDate = convertSalesforceDateTime(
+      data.LastModifiedDate,
+    );
+    transformations.push(`LastModifiedDate`);
+  }
+
+  if (data?.IsEscalated !== undefined) {
+    caseData.escalated = Boolean(data.IsEscalated);
+    transformations.push(`IsEscalated`);
+  }
+
+  if (data?.LastReferencedDate) {
+    caseData.lastReferencedDate = convertSalesforceDateTime(
+      data.LastReferencedDate,
+    );
+    transformations.push(`LastReferencedDate`);
+  }
+
+  if (data?.LastViewedDate) {
+    caseData.lastViewedDate = convertSalesforceDateTime(data.LastViewedDate);
+    transformations.push(`LastViewedDate`);
+  }
+
+  if (data?.CreatedDate) {
+    caseData.createdDate = convertSalesforceDateTime(data.CreatedDate);
+    transformations.push(`CreatedDate`);
+  }
+
+  if (data?.IsDeleted !== undefined) {
+    caseData.deleted = Boolean(data.IsDeleted);
+    transformations.push(`IsDeleted`);
+  }
+
+  if (data?.IsClosed !== undefined) {
+    caseData.closed = Boolean(data.IsClosed);
+    transformations.push(`IsClosed`);
+  }
+
+  if (data?.ClosedDate) {
+    caseData.dateTimeClosed = convertSalesforceDateTime(data.ClosedDate);
+    transformations.push(`ClosedDate`);
+  }
+
+  if (transformations.length > 0) {
+    logger.debug(`🔄 Applied ${transformations.length} field transformations`, {
+      transformations,
+    });
+  }
+
+  return caseData;
+}
+
+/**
+ * Convert Salesforce DateTime format
+ * From "yyyy-MM-dd'T'HH:mm:ss.SSSXXXX" to "yyyy-MM-dd'T'HH:mm:ssxxx"
+ */
+function convertSalesforceDateTime(dateTimeStr: string): string {
+  try {
+    const date = new Date(dateTimeStr);
+    const isoString = date.toISOString();
+    // Convert to timezone offset format
+    const result = isoString.replace(`Z`, `+00:00`);
+    logger.debug(`🕒 Converted datetime format`, {
+      input: dateTimeStr,
+      output: result,
+    });
+    return result;
+  } catch (error) {
+    logger.warn(
+      `⚠️ Failed to convert Salesforce datetime, returning original`,
+      {
+        dateTimeStr,
+        error: error instanceof Error ? error.message : String(error),
+      },
+    );
+    return dateTimeStr; // Return original value if conversion fails
+  }
+}
+
+/**
+ * Route by action type - corresponds to action-type choice selector
+ */
+async function routeByActionType(payload: TransformedPayload): Promise<void> {
+  const actionType = payload.platformEvent.actionType;
+  logger.debug(` Routing by action type`, {actionType});
+
+  if (actionType === CONSTANTS.ACTION_NEW) {
+    logger.info(` Creating new case in AEP`);
+    await createCaseInAEP(payload);
+  } else if (actionType === CONSTANTS.ACTION_UPDATE) {
+    logger.info(` Updating existing case in AEP`);
+    await updateCaseInAEP(payload);
+  } else {
+    const errorMsg = `Invalid Action-type: ${actionType}`;
+    logger.error(`❌ Invalid action type received`, {
+      actionType,
+      validTypes: [CONSTANTS.ACTION_NEW, CONSTANTS.ACTION_UPDATE],
+    });
+    throw new Error(errorMsg);
+  }
+}
+
+/**
+ * Create Case in AEP - corresponds to create-case-in-aep-subflow
+ * Uses the new AEP Case processing module
+ */
+async function createCaseInAEP(payload: TransformedPayload): Promise<void> {
+  logger.debug(` Creating case in AEP`, {
+    salesforceRecordId: payload.platformEvent.salesforceRecordId,
+    parentRecordType: payload.platformEvent.parentRecordType,
+  });
+
+  try {
+    // Determine if this is B2C or B2B based on parent record type
+    const isB2C =
+      payload.platformEvent.parentRecordType ===
+        CONSTANTS.ACCOUNT_TYPE_PERSON_ACC ||
+      CONSTANTS.LEAD_RECORDS.includes(payload.platformEvent.parentRecordType);
+
+    // Send to AEP using the reusable function
+    await sendCaseToAEP(payload, isB2C);
+
+    logger.info(`✅ Case creation successfully executed in AEP`, {
+      salesforceRecordId: payload.platformEvent.salesforceRecordId,
+      customerID: payload.customerID,
+      isB2C,
+    });
+  } catch (error) {
+    logger.error(`💥 Failed to create case in AEP`, {
+      error: error instanceof Error ? error.message : String(error),
+      salesforceRecordId: payload.platformEvent.salesforceRecordId,
+      customerID: payload.customerID,
+    });
+    throw error;
+  }
+}
+
+/**
+ * Update Case in AEP - corresponds to update-case-in-aep-subflow
+ * Uses the same AEP Case processing module as create
+ */
+async function updateCaseInAEP(payload: TransformedPayload): Promise<void> {
+  logger.debug(`📤 Updating case in AEP`, {
+    salesforceRecordId: payload.platformEvent.salesforceRecordId,
+    parentRecordType: payload.platformEvent.parentRecordType,
+  });
+
+  try {
+    // Determine if this is B2C or B2B based on parent record type
+    const isB2C =
+      payload.platformEvent.parentRecordType ===
+        CONSTANTS.ACCOUNT_TYPE_PERSON_ACC ||
+      CONSTANTS.LEAD_RECORDS.includes(payload.platformEvent.parentRecordType);
+
+    // Send to AEP using the reusable function (same as create)
+    await sendCaseToAEP(payload, isB2C);
+
+    logger.info(`✅ Case update successfully executed in AEP`, {
+      salesforceRecordId: payload.platformEvent.salesforceRecordId,
+      customerID: payload.customerID,
+      isB2C,
+    });
+  } catch (error) {
+    logger.error(`💥 Failed to update case in AEP`, {
+      error: error instanceof Error ? error.message : String(error),
+      salesforceRecordId: payload.platformEvent.salesforceRecordId,
+      customerID: payload.customerID,
+    });
+    throw error;
+  }
+}

