+/**
+ * Process single customer feed event - encapsulated core logic
+ */
+async function processSingleFeedEvent(
+  feedItem: SimplifiedPayload,
+): Promise<void> {
+  try {
+    // Step 1: Platform event transformation (corresponds to platform-event-transformation)
+    const transformedPayload = transformPlatformEvent(feedItem);
+    logger.debug(`✅ Platform event transformation completed`);
+
+    // Step 2: Object type routing (corresponds to sObject-Name choice)
+    const preparedPayload = routeByObjectType(transformedPayload);
+    logger.debug(`✅ Object type routing completed`, {
+      objectType: preparedPayload.platformEvent.objectType,
+      recordType: preparedPayload.platformEvent.recordType,
+    });
+
+    // Step 3: Action type routing (corresponds to event-action choice)
+    await routeByActionType(preparedPayload);
+    logger.debug(`✅ Action type routing completed`);
+
+    logger.info(`✅ Customer Feed item processed successfully`, {
+      objectType: preparedPayload.platformEvent.objectType,
+      actionType: preparedPayload.platformEvent.actionType,
+    });
+  } catch (error) {
+    logger.error(`❌ Failed to process Customer Feed item`, {
+      error: error instanceof Error ? error.message : String(error),
+      stack: error instanceof Error ? error.stack : undefined,
+    });
+    throw error;
+  }
+}
