+/**
+ * Main handler function
+ */
+export const handler = async (event: CustomerFeedEvent, _context: Context) => {
+  logger.info(`🚀 Processing Customer Feed event`, {
+    eventId: event.id,
+    source: event.source,
+    detailType: Array.isArray(event.detail) ? `array` : typeof event.detail,
+    detailCount: Array.isArray(event.detail) ? event.detail.length : 1,
+    replayId: event[`replay-id`],
+  });
+
+  try {
+    // Use the reusable array processing function
+    await processEventArray(event.detail, processSingleFeedEvent, logger);
+
+    return {
+      statusCode: 200,
+      body: JSON.stringify({
+        message: `Customer Feed event processed successfully`,
+        eventId: event.id,
+      }),
+    };
+  } catch (error) {
+    logger.error(`❌ Failed to process Customer Feed event`, {
+      error: error instanceof Error ? error.message : String(error),
+      stack: error instanceof Error ? error.stack : undefined,
