+/**
+ * Route by object type (equivalent to sObject-Name choice in XML)
+ */
+function routeByObjectType(payload: any): TransformedPayload {
+  try {
+    const objectType = payload.Object_Name__c;
+    const recordType = payload.Record_Type__c;
+    logger.debug(`🔄 Routing by object type`, {
+      objectType,
+      recordType,
+    });
+
+    const basePayload: TransformedPayload = {
+      platformEvent: {
+        registrationType: payload.Data__c?.Registration_Type__c,
+        objectType,
+        salesforceRecordId: payload.Record_ID__c,
+        recordType,
+        actionType: payload.Action__c,
+        createDate: payload.Data__c?.CreatedDate,
+        modifyDate: payload.Data__c?.LastModifiedDate,
+        currencyIsoCode: payload.Data__c?.CurrencyIsoCode,
+        incoTerms: payload.Data__c?.IncoTerms__c,
+        paymentTerms: payload.Data__c?.PaymentTerms__c,
+        isCompleteAddress: payload.Data__c?.Is_Complete_Address__c,
+        taxClassification: payload.Data__c?.TaxCI__c,
+        documentCheckStatus: payload.Data__c?.Document_Check_Status__c,
+      },
+      customerID: payload.Data__c?.Id,
+      ecid: payload.Data__c?.eco_Experience_ID__c,
+    };
+
+    // Route based on object type
+    if (objectType === CONSTANTS.ACCOUNT_TYPE_LEAD) {
+      return prepareLeadRequest(payload, basePayload);
+    } else if (
+      objectType === CONSTANTS.ACCOUNT_TYPE_ACCOUNT &&
+      recordType === CONSTANTS.ACCOUNT_TYPE_PERSON_ACC
+    ) {
+      return prepareB2CAccountRequest(payload, basePayload);
+    } else if (
+      objectType === CONSTANTS.ACCOUNT_TYPE_ACCOUNT &&
+      CONSTANTS.ACCOUNT_TYPE_BUSINESS_ACC.includes(recordType)
+    ) {
+      return prepareB2BAccountRequest(payload, basePayload);
+    } else if (objectType === CONSTANTS.ACCOUNT_TYPE_CONTACT) {
+      return prepareContactRequest(payload, basePayload);
+    } else if (objectType === CONSTANTS.ACCOUNT_TYPE_INTEREST) {
+      return prepareInterestRequest(payload, basePayload);
+    } else {
+      logger.warn(`⚠️ Unsupported object type`, {
+        objectType,
+        recordType,
+      });
+      throw new Error(`Unsupported object type: ${objectType}`);
+    }
+  } catch (error) {
+    logger.error(`❌ Object type routing failed`, {
+      error: error instanceof Error ? error.message : String(error),
+    });
+    throw error;
+  }
+}
