import {logger} from '@api-integration-aws/core/util';
import {sendEvent} from '@api-integration-aws/core/util/event-publish';
import {formatResponse} from '@smart/feature-app/node';
import {ApiHandler} from 'sst/node/api';
import {middyfy} from '../../middleware/middy';
import {parseEvent} from '../../utils/parse-event';
import {
  EventBusProxyRequestSchema,
  EventBusProxyResponseSchema,
} from './schema';

/**
 * Generic EventBus proxy Lambda function
 * Allows third-party platforms to send events to the specified EventBus through this function
 *
 * @param event - Request body containing Source, DetailType, Detail, EventBusName
 * @returns Sending result
 */
const handler = ApiHandler(async (event) => {
  logger.info(`🚀 Received EventBus proxy request`);

  try {
    // Use parseEvent to parse and validate the event
    const {bodyData} = parseEvent(event, {
      BodySchema: EventBusProxyRequestSchema,
    });

    logger.info(`📤 Sending event to EventBus`, {
      source: bodyData.Source,
      detailType: bodyData.DetailType,
    });

    // Send event to EventBus
    await sendEvent({
      Source: bodyData.Source, // Now supports EventBusSource enum values
      DetailType: bodyData.DetailType,
      Detail: bodyData.Detail,
    });

    logger.info(`✅ Event successfully sent to EventBus`, {
      source: bodyData.Source,
      detailType: bodyData.DetailType,
    });

    // Construct successful response
    const response = {
      success: true,
    };

    // Validate response format
    const responseValidation = EventBusProxyResponseSchema.safeParse(response);
    if (!responseValidation.success) {
      logger.error(`❌ Response validation failed`, {
        errors: responseValidation.error.issues,
      });
    }

    return formatResponse(200, response);
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    logger.error(`❌ Failed to send event to EventBus`, {
      error: errorMessage,
      stack: error instanceof Error ? error.stack : undefined,
    });

    // Construct error response
    const errorResponse = {
      success: false,
      error: `Failed to send event: ${errorMessage}`,
    };

    // Validate error response format
    const responseValidation =
      EventBusProxyResponseSchema.safeParse(errorResponse);
    if (!responseValidation.success) {
      logger.error(`❌ Error response validation failed`, {
        errors: responseValidation.error.issues,
      });
    }

    return formatResponse(400, errorResponse);
  }
});

export const main = middyfy(handler);

