+ * Corresponds to prepare-interest-request transform in XML
+ */
+const prepareInterestRequest = (
+  bodyData: CustomerRegistrationPutBody,
+  accountSearch: any,
+  regToken: string | undefined,
+  headersData: CustomerRegistrationPutHeaders,
+) => {
+  const requestData: any = {
+    ...(regToken && {regToken}),
+    regSource: headersData[`x-channel`],
+    muteWebhooks: true,
+    profile: {
+      email: bodyData.email,
+    },
+  };
+
+  // Prepare subscriptions data based on existing subscriptions and new interest data
+  if (bodyData.interest) {
+    requestData.subscriptions = prepareInterestSubscriptions(
+      accountSearch?.subscriptions || {},
+      bodyData.interest,
+    );
+  }
+
+  return skipNullsEverywhere(requestData);
+};
+
+/**
+ * Prepare interest subscriptions data
+ * Handles merging existing subscriptions with new interest data
+ */
+const prepareInterestSubscriptions = (
+  existingSubscriptions: any,
+  interestData: CustomerRegistrationPutBody['interest'],
+) => {
+  const subscriptions: any = {};
+
+  // Handle smart_NLwithDOI_EU subscription
+  if (existingSubscriptions.smart_NLwithDOI_EU) {
+    subscriptions.smart_NLwithDOI_EU = {
+      email: {
+        isSubscribed:
+          existingSubscriptions.smart_NLwithDOI_EU.email?.isSubscribed ?? true,
+      },
+    };
+
+    // Handle tags merging logic from XML
+    if (
+      existingSubscriptions.smart_NLwithDOI_EU.tags &&
+      interestData?.productInterest
+    ) {
+      const existingTags = existingSubscriptions.smart_NLwithDOI_EU.tags;
+      const newTag = {
+        ...(interestData.productInterest && {
+          productInterest: interestData.productInterest,
+        }),
+        ...(interestData.eventName && {eventName: interestData.eventName}),
+        ...(interestData.lineInterests && {
+          lineInterests: interestData.lineInterests
+            .split(`,`)
+            .map((item: string) => item.trim()),
+        }),
+        ...(interestData[`X-Campaign-id`] && {
+          'X-Campaign-id': interestData[`X-Campaign-id`],
+        }),
+      };
+
+      // Merge with existing tags, avoiding duplicates
+      const mergedTags = [...existingTags];
+      if (Object.keys(newTag).length > 0) {
+        mergedTags.push(JSON.stringify(newTag));
+      }
+
+      subscriptions.smart_NLwithDOI_EU.email.tags = mergedTags;
+    } else if (
+      interestData?.[`X-Campaign-id`] ||
+      interestData?.productInterest ||
+      interestData?.eventName ||
+      interestData?.lineInterests
+    ) {
+      // Create new tags array if none exist
+      subscriptions.smart_NLwithDOI_EU.email.tags = [
+        JSON.stringify({
+          ...(interestData.productInterest && {
+            productInterest: interestData.productInterest,
+          }),
+          ...(interestData.eventName && {eventName: interestData.eventName}),
+          ...(interestData.lineInterests && {
+            lineInterests: interestData.lineInterests
+              .split(`,`)
+              .map((item: string) => item.trim()),
+          }),
+          ...(interestData[`X-Campaign-id`] && {
+            'X-Campaign-id': interestData[`X-Campaign-id`],
+          }),
+        }),
+      ];
+    }
+  }
+
+  return subscriptions;
