+        _id: headersData[`x-correlation-id`] || `correlation-${Date.now()}`,
+        _smarteurope: {
+          campaignSubscriptions: {
+            campaignDetails: {
+              campaignGroup: bodyData.interest?.[`X-Campaign-id`],
