/**
 * Map consents function
 * Replicates the functionality of the DataWeave custom function for mapping consents
 * from the request payload to the format expected by CDC
 */

// Define types for the consents structure
interface ConsentItem {
  Name: string;
  isConsentGranted?: boolean | string;
  isSubscribed?: boolean | string;
}

interface ConsentsPayload {
  Subscriptions?: ConsentItem[];
  Preferences?: ConsentItem[];
  [key: string]: any;
}

interface MappedConsents {
  subscriptions?: Record<
    string,
    {email: {isSubscribed: boolean; tags?: string[]}}
  >;
  preferences?: Record<
    string,
    | {isConsentGranted: boolean}
    | {
        [key: string]: {isConsentGranted: boolean};
      }
  >;
  [key: string]: any;
}

/**
 * Maps consents from the request payload to the format expected by CDC
 * Replicates the DataWeave function from customFunctions.dwl
 * @param requestPayload - The consents payload from the request
 * @returns Mapped consents object
 */
export function mapConsents(requestPayload: ConsentsPayload): MappedConsents {
  const result: MappedConsents = {};

  // Process each key in the request payload
  for (const [key, value] of Object.entries(requestPayload)) {
    if (key.toLowerCase().includes(`subscriptions`) && Array.isArray(value)) {
      // Handle subscriptions
      const subscriptions: Record<string, {email: {isSubscribed: boolean}}> =
        {};
      for (const item of value) {
        subscriptions[item.Name] = {
          email: {
            isSubscribed: Boolean(item.isSubscribed),
          },
        };
      }
      result.subscriptions = subscriptions;
    } else if (
      key.toLowerCase().includes(`preferences`) &&
      Array.isArray(value)
    ) {
      // Handle preferences - first convert to object format
      const preferences: Record<string, {isConsentGranted: boolean}> = {};
      for (const item of value) {
        preferences[item.Name] = {
          isConsentGranted: Boolean(item.isConsentGranted),
        };
      }

      // Apply special mapping for terms and privacy to match DataWeave logic
      const mappedPreferences: Record<
        string,
        | {isConsentGranted: boolean}
        | {
            [key: string]: {isConsentGranted: boolean};
          }
      > = {};

      for (const [prefKey, prefValue] of Object.entries(preferences)) {
        if (prefKey.toLowerCase().includes(`smart_termsofservice`)) {
          // For terms, create a nested structure: { "terms": { [prefKey]: prefValue } }
          mappedPreferences.terms = {
            ...mappedPreferences.terms,
            [prefKey]: prefValue,
          };
        } else if (prefKey.toLowerCase().includes(`privacy`)) {
          // For privacy, create a nested structure: { "privacy": { [prefKey]: prefValue } }
          mappedPreferences.privacy = {
            ...mappedPreferences.privacy,
            [prefKey]: prefValue,
          };
        } else {
          // For other preferences, add them directly
          mappedPreferences[prefKey] = prefValue;
        }
      }

      result.preferences = mappedPreferences;
    } else {
      // Handle other keys
      result[key] = value;
    }
  }

  return result;
}

