import type {StackContext} from 'sst/constructs';
import {Config} from 'sst/constructs';
import {isLocalStack} from './utils';

export function ConfigStack({app, stack}: StackContext) {
  const isLocal = isLocalStack(app.stage);
  const apiKey = new Config.Secret(stack, `API_KEY`);
  const target = new Config.Parameter(stack, `TARGET`, {
    value: isLocal ? (process.env.TARGET ?? `dev`) : app.stage,
  });

  // All endpoint configs
  const PSPConfig = new Config.Secret(stack, `PSPConfig`);
  const vdpConfig = new Config.Secret(stack, `VDPConfig`);
  const salesforceConfig = new Config.Secret(stack, `SalesforceConfig`);
  const aftersalesConfig = new Config.Secret(stack, `AftersalesConfig`);
  const IDAConfig = new Config.Secret(stack, `IDAConfig`);
  const CDCConfig = new Config.Secret(stack, `CDCConfig`);
  const ECOMConfig = new Config.Secret(stack, `ECOMConfig`);
  const OIDCConfig = new Config.Secret(stack, `OIDCConfig`);
  const OIDCClients = new Config.Secret(stack, `OIDCClients`);
  const MCSDbCredentials = new Config.Secret(stack, `MCSDbCredentials`);
  const DMPConfig = new Config.Secret(stack, `DMPConfig`);
  const ALDConfig = new Config.Secret(stack, `ALDConfig`);
  const ARCConfig = new Config.Secret(stack, `ARCConfig`);
  const SLServiceConfig = new Config.Secret(stack, `SLServiceConfig`);
  const ONFIDOConfig = new Config.Secret(stack, `ONFIDOConfig`);
  const EXTConfig = new Config.Secret(stack, `EXTConfig`);
  const MulsoftConfig = new Config.Secret(stack, `MulsoftConfig`);
  const AEPConfig = new Config.Secret(stack, `AEPConfig`);
  const AzureStorageConfig = new Config.Secret(stack, `AzureStorageConfig`);
  const CPIConfig = new Config.Secret(stack, `CPIConfig`);
  const TSPConfig = new Config.Secret(stack, `TSPConfig`);
  const AEPExtendConfig = new Config.Secret(stack, `AEPExtendConfig`);
  const SEDConfig = new Config.Secret(stack, `SEDConfig`);
  const PSPSignatureConfig = new Config.Secret(stack, `PSPSignatureConfig`);
  const PSPCertificateConfig = new Config.Secret(stack, `PSPCertificateConfig`);
  const SalesforceEventConfig = new Config.Secret(
    stack,
    `SalesforceEventConfig`,
  );

  return {
    vdpConfig,
    apiKey,
    salesforceConfig,
    aftersalesConfig,
    CDCConfig,
    ECOMConfig,
    OIDCConfig,
    OIDCClients,
    MCSDbCredentials,
    DMPConfig,
    target,
    ALDConfig,
    ARCConfig,
    SLServiceConfig,
    ONFIDOConfig,
    PSPConfig,
    IDAConfig,
    EXTConfig,
    MulsoftConfig,
    AEPConfig,
    AzureStorageConfig,
    CPIConfig,
    TSPConfig,
    AEPExtendConfig,
    SEDConfig,
    PSPSignatureConfig,
    PSPCertificateConfig,
    SalesforceEventConfig,
  };
}

