import type {StackContext} from 'sst/constructs';
import {Api, use} from 'sst/constructs';
import {AuthorizerFunctions} from '../function-stacks/AuthorizerFunctions';
import {MiscFunctions} from '../function-stacks/MiscFunctions';
import {accessLog, cors} from '../utils';

export function MiscApiStack({stack}: StackContext) {
  const {authorizer, cdcAuthorizer} = use(AuthorizerFunctions);
  const {
    updateAddress,
    getAddress,
    deleteAddress,
    deleteCustomer,
    createAddress,
    payment,
    paymentIdeal,
    getCustomerByUuid,
    idaCustomerDetail,
    idaCustomer,
    customerInteractions,
    PostRsaBreakdownCase,
    PutRsaBreakdownCase,
    updateCustomerByUuid,
    customerRegistrationPOST,
    customerRegistrationPUT,
    updateOrders,
    chatbotCustomer,
    eventBusProxy,
  } = use(MiscFunctions);

  const miscApi = new Api(stack, `MiscApi`, {
    accessLog,
    cors,
    authorizers: {
      lambdaAuthorizer: {
        type: `lambda`,
        function: authorizer,
        identitySource: [],
        responseTypes: [`simple`],
      },
      cdcAuthorizer: {
        type: `lambda`,
        function: cdcAuthorizer,
        identitySource: [],
        responseTypes: [`simple`],
      },
    },
    defaults: {
      authorizer: `lambdaAuthorizer`,
    },
    routes: {
      'PUT /v1/address': {
        function: updateAddress,
      },
      'POST /v1/address': {
        function: createAddress,
      },
      'GET /v1/address': {
        function: getAddress,
      },
      'DELETE /v1/address': {
        function: deleteAddress,
      },
      'DELETE /v1/customer/{uuid}': {
        function: deleteCustomer,
      },
      'POST /v1/payment/ideal': {
        function: paymentIdeal,
        authorizer: `cdcAuthorizer`,
      },
      'POST /v1/payment': {
        function: payment,
        authorizer: `cdcAuthorizer`,
      },
      'GET /v1/customer/{uuid}': {
        function: getCustomerByUuid,
        authorizer: `cdcAuthorizer`,
      },
      'PUT /v1/customer/{uuid}': {
        function: updateCustomerByUuid,
        authorizer: `cdcAuthorizer`,
      },
      'POST /v1/ida-customer': {
        function: idaCustomer,
        authorizer: `cdcAuthorizer`,
      },
      'GET /v1/ida-customer/keyring': {
        function: idaCustomerDetail,
        authorizer: `cdcAuthorizer`,
      },
      'PUT /v1/customer-registration': {
        function: customerRegistrationPUT,
      },
      'GET /v1/customer-interactions/{uid}': {
        function: customerInteractions,
      },
      'POST /v1/rsa/breakdown-case': {
        function: PostRsaBreakdownCase,
      },
      'PUT /v1/rsa/breakdown-case/{caseId}': {
        function: PutRsaBreakdownCase,
      },
      'POST /v1/customer-registration': {
        function: customerRegistrationPOST,
      },
      'GET /v1/chatbot/customer-preview': {
        function: chatbotCustomer,
        authorizer: `cdcAuthorizer`,
      },
      'PUT /v1/update-orders': {
        function: updateOrders,
      },
      'PUT /v1/customer-sf/{uuid}': {
        function: updateCustomerByUuid,
      },
      'POST /v1/event-bus-proxy': {
        function: eventBusProxy,
      },
    },
  });

  return {
    api: miscApi,
  };
}

